## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/rfaLogic.ts`

```typescript
export type SpineRegion = "lumbar" | "cervical" | "thoracic" | "sacroiliac";

export type RFAInput = {
  age: string; spineRegion: string; symptomDurationMonths: string;
  painScore: string; symptoms: string[];
  diagnosticBlock1Relief: string; diagnosticBlock2Relief: string;
  activeInfection: boolean; coagulopathy: boolean; allergy: boolean;
  pacemaker: boolean; pregnancy: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessRFA(input: RFAInput) {
  const block1 = parseFloat(input.diagnosticBlock1Relief) || 0;
  const block2 = parseFloat(input.diagnosticBlock2Relief) || 0;
  const symptomMonths = parseFloat(input.symptomDurationMonths) || 0;
  const painScore = parseFloat(input.painScore) || 0;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active infection — absolute contraindication");
  if (input.coagulopathy) contraindications.push("Uncorrected coagulopathy");
  if (input.allergy) contraindications.push("Allergy to local anesthetic or contrast");
  if (input.pregnancy) contraindications.push("Pregnancy — avoid fluoroscopy");
  if (input.pacemaker) contraindications.push("Pacemaker/ICD — relative contraindication; use bipolar technique; cardiology consultation");

  const hardContraindications = contraindications.filter(c => !c.includes("relative") && !c.includes("Pacemaker"));
  if (hardContraindications.length > 0) {
    return { recommendation: "RFA Contraindicated", cor: "III" as COR, loe: "C", urgency: "Contraindicated", rationale: ["Absolute contraindications identified."], contraindications, optimizationSteps: [] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  const bothBlocksPositive = block1 >= 80 && block2 >= 80;
  const oneBlockPositive = (block1 >= 80 || block2 >= 80) && !(block1 >= 80 && block2 >= 80);

  if (bothBlocksPositive && symptomMonths >= 3) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Two positive diagnostic medial branch blocks (≥80% relief each) — gold standard for RFA candidacy");
    rationale.push("Chronic pain (≥3 months) with facetogenic source confirmed");
    rationale.push("RFA is strongly recommended per ASIPP guidelines");
  } else if (oneBlockPositive && symptomMonths >= 3) {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("One positive diagnostic block — second confirmatory block recommended before RFA");
    rationale.push("Some payers accept single block with ≥80% relief; verify payer policy");
    optimizationSteps.push("Perform second diagnostic medial branch block to confirm facetogenic source");
  } else if (block1 < 80 && block2 < 80 && (block1 > 0 || block2 > 0)) {
    cor = "III"; urgency = "Not Indicated";
    rationale.push("Diagnostic blocks did not achieve ≥80% relief — facetogenic source not confirmed");
    rationale.push("RFA is not indicated without positive diagnostic blocks");
    optimizationSteps.push("Re-evaluate pain generator — consider discogenic, sacroiliac, or myofascial sources");
    optimizationSteps.push("Consider alternative interventions: ESI, SI joint injection, or pain psychology");
  } else {
    cor = "IIb"; urgency = "Diagnostic Blocks Required";
    rationale.push("Diagnostic medial branch blocks have not been performed or results not entered");
    optimizationSteps.push("Perform two diagnostic medial branch blocks before proceeding with RFA");
    optimizationSteps.push("Document ≥80% pain relief from each block");
  }

  if (painScore >= 7) rationale.push("Severe pain (NRS ≥7) supports intervention");
  if (input.pacemaker) optimizationSteps.push("Pacemaker present — use bipolar RFA technique; obtain cardiology clearance");

  return { recommendation: cor === "I" ? "RFA Recommended" : cor === "IIa" ? "RFA Reasonable (Second Block Needed)" : cor === "III" ? "RFA Not Indicated" : "Diagnostic Blocks Required First", cor, loe: bothBlocksPositive ? "A" : "B", urgency, rationale, contraindications, optimizationSteps };
}
